style.css:
body {
    background-image: url("https://i.pinimg.com/1200x/64/35/13/64351303ccd6104628426030091340ff.jpg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
}

body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(255, 230, 242, 0.18);
    pointer-events: none;
    z-index: -1;
}
